def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    first = {"id": "a", "day": 1, "flagged": True}
    last = {"id": "a", "day": 3, "flagged": False}
    same_day = {"id": "b", "day": 3, "flagged": True}
    earlier = {"id": "z", "day": 2, "flagged": None}
    assert dedupe_transcripts([first, same_day, earlier, last]) == [earlier, last, same_day]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]


def test_monitor_summary_uses_pooled_rate_and_calendar_days():
